// budget-enforcement.js
async function enforceBudget(tenantId, epsilon) {
  const budget = await db.get(`dp-budget:${tenantId}`)
  if (budget.remaining < epsilon) throw new Error('Budget exhausted')
  await db.update(`dp-budget:${tenantId}`, { remaining: budget.remaining - epsilon })
}
```
